shell_commands:
node -e "
const fs = require('fs');
const path = require('path');
const pkgDir = path.dirname(require.resolve('@re-cinq/eslint-plugin-re-lint/package.json'));
const walk = d => fs.readdirSync(d, {withFileTypes: true}).flatMap(e => e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]);
console.log(walk(pkgDir).map(f => path.relative(pkgDir, f)).join('\n'));
"

